/**
 * Generated by `createservice subscription.RequestSubscriptionInvoiceService --type mutations`
 */
const { GQLError, GQLErrorCode: { BAD_USER_INPUT } } = require('@open-condo/keystone/errors')
const { getLogger } = require('@open-condo/keystone/logging')
const { GQLCustomSchema, find } = require('@open-condo/keystone/schema')

const { NOT_FOUND } = require('@condo/domains/common/constants/errors')
const access = require('@condo/domains/subscription/access/RequestSubscriptionInvoiceService')
const { SUBSCRIPTION_CONTEXT_STATUS, SUBSCRIPTION_PAYMENT_TYPE_INVOICE } = require('@condo/domains/subscription/constants')
const { checkSubscriptionInvoiceRequestLimit } = require('@condo/domains/subscription/utils/serverSchema/subscriptionInvoiceRequestLimit')
const { queueSubscriptionInvoiceRequestedWebhook } = require('@condo/domains/subscription/utils/serverSchema/subscriptionWebhooks')

const logger = getLogger('RequestSubscriptionInvoiceService')

/**
 * List of possible errors, that this custom schema can throw
 * They will be rendered in documentation section in GraphiQL for this custom schema
 */
const ERRORS = {
    SUBSCRIPTION_CONTEXT_NOT_FOUND: {
        mutation: 'requestSubscriptionInvoice',
        variable: ['data', 'subscriptionContexts'],
        code: BAD_USER_INPUT,
        type: NOT_FOUND,
        message: 'SubscriptionContext not found',
    },
    SUBSCRIPTION_CONTEXTS_FROM_DIFFERENT_ORGANIZATIONS: {
        mutation: 'requestSubscriptionInvoice',
        variable: ['data', 'subscriptionContexts'],
        code: BAD_USER_INPUT,
        type: 'SUBSCRIPTION_CONTEXTS_FROM_DIFFERENT_ORGANIZATIONS',
        message: 'All subscription contexts must belong to the same organization',
    },
    INVOICE_NOT_AWAITING_PAYMENT: {
        mutation: 'requestSubscriptionInvoice',
        variable: ['data', 'subscriptionContexts'],
        code: BAD_USER_INPUT,
        type: 'INVOICE_NOT_AWAITING_PAYMENT',
        message: 'Only a subscription registered to be paid by invoice and still waiting for the payment can have its invoice requested',
    },
}

const RequestSubscriptionInvoiceService = new GQLCustomSchema('RequestSubscriptionInvoiceService', {
    types: [
        {
            access: true,
            type: 'input RequestSubscriptionInvoiceInput { dv: Int!, sender: SenderFieldInput!, subscriptionContexts: [SubscriptionContextWhereUniqueInput!]! }',
        },
        {
            access: true,
            type: 'type RequestSubscriptionInvoiceOutput { subscriptionContexts: [SubscriptionContext!]! }',
        },
    ],

    mutations: [
        {
            access: access.canRequestSubscriptionInvoice,
            schema: 'requestSubscriptionInvoice(data: RequestSubscriptionInvoiceInput!): RequestSubscriptionInvoiceOutput',
            doc: {
                summary: 'Sends a webhook to deliver once more the invoices already issued for the given subscription contexts. Nothing new is registered and the payment deadline stays the same',
                errors: ERRORS,
            },
            resolver: async (parent, args, context) => {
                const { data: { sender, subscriptionContexts: subscriptionContextsInput } } = args

                const subscriptionContextIds = [...new Set(subscriptionContextsInput.map(({ id }) => id))]
                const subscriptionContexts = await find('SubscriptionContext', { id_in: subscriptionContextIds, deletedAt: null })
                if (subscriptionContextIds.length === 0 || subscriptionContexts.length !== subscriptionContextIds.length) {
                    throw new GQLError(ERRORS.SUBSCRIPTION_CONTEXT_NOT_FOUND, context)
                }

                const organizationIds = [...new Set(subscriptionContexts.map(subscriptionContext => subscriptionContext.organization))]
                if (organizationIds.length > 1) {
                    throw new GQLError(ERRORS.SUBSCRIPTION_CONTEXTS_FROM_DIFFERENT_ORGANIZATIONS, context)
                }

                // A created context of an invoice registration is exactly an invoice nobody has paid yet
                const isAwaitingInvoicePayment = (subscriptionContext) => subscriptionContext.status === SUBSCRIPTION_CONTEXT_STATUS.CREATED
                    && Boolean(subscriptionContext.invoice)
                    && subscriptionContext.frozenPaymentInfo?.paymentType === SUBSCRIPTION_PAYMENT_TYPE_INVOICE
                if (!subscriptionContexts.every(isAwaitingInvoicePayment)) {
                    throw new GQLError(ERRORS.INVOICE_NOT_AWAITING_PAYMENT, context)
                }

                // Features of one alert may sit on different invoices: each invoice is a request of its own
                const invoiceIds = [...new Set(subscriptionContexts.map(subscriptionContext => subscriptionContext.invoice))]
                for (const invoiceId of invoiceIds) {
                    const invoiceContexts = await find('SubscriptionContext', { invoice: { id: invoiceId }, deletedAt: null })

                    await checkSubscriptionInvoiceRequestLimit(context, 'resend', organizationIds[0], invoiceContexts.map(invoiceContext => invoiceContext.subscriptionPlan))

                    await queueSubscriptionInvoiceRequestedWebhook({
                        invoiceId,
                        subscriptionContexts: invoiceContexts,
                        userId: context.authedItem?.id,
                        isRepeated: true,
                        sender,
                    })
                }
                logger.info({ msg: 'Requested subscription invoices again', data: { organizationId: organizationIds[0], invoiceIds } })

                return { subscriptionContexts }
            },
        },
    ],

})

module.exports = {
    RequestSubscriptionInvoiceService,
    ERRORS,
}
